import copy
import logging

from ute_common_abstract_core.message import NotFoundKey, AmbiguousKey, MessageField
import pprint

LOGGER_DETAILS = {"reportConfig": None, "measObject": None}


def meas_object_factory(measObject):
    supported_object_types = {"measObject": MeasObject}
    for supported_object_type in supported_object_types:
        if supported_object_type in measObject:
            return supported_object_types[supported_object_type](measObject)
    logging.getLogger("ta_measurements").debug(
        "Cannot create measurement object for raw measurement: {},"
        " only supported types: {}".format(measObject, list(supported_object_types.keys()))
    )


def report_config_object_factory(reportConfig):
    supported_object_types = {"reportConfig": ReportConfig}
    for supported_object_type in supported_object_types:
        if supported_object_type in reportConfig:
            return supported_object_types[supported_object_type](reportConfig)
    logging.getLogger("ta_measurements").debug(
        "Cannot create report config object for raw measurement: {},"
        " only supported types: {}".format(reportConfig, list(supported_object_types.keys()))
    )


class MeasItem(MessageField):
    def __getattr__(self, attr):
        try:
            return self.get_value_by_unique_key(attr)
        except NotFoundKey:
            raise AttributeError("'%s' object has no attribute '%s'" % (self, attr))
        except AmbiguousKey:
            raise AttributeError("'%s' object has too many attributes '%s'" % (self, attr))


class MeasObject(MeasItem):
    def __init__(self, meas_object):
        super(MeasObject, self).__init__(meas_object["measObject"])
        self["measObjectId"] = meas_object["measObjectId"]


class ReportConfig(MeasItem):
    def __init__(self, report_config):
        super(ReportConfig, self).__init__(report_config["reportConfig"])
        self["reportConfigId"] = report_config["reportConfigId"]


class MeasId(MeasItem):
    def __init__(self, meas_id):
        super(MeasId, self).__init__(meas_id)


class MeasurementConfiguration(object):
    def __init__(
        self,
        meas_object_to_add_mod_list,
        report_config_to_add_mod_list,
        meas_id_to_add_mod_list,
        meas_object_to_add_mod_list_v9e0,
    ):
        self.measObjects = {}
        self.reportConfigs = {}
        self.measIds = {}
        self.activeConfigs = None
        self.update(
            meas_object_to_remove_list=None,
            report_config_to_remove_list=None,
            meas_id_to_remove_list=None,
            meas_object_to_add_mod_list=meas_object_to_add_mod_list,
            report_config_to_add_mod_list=report_config_to_add_mod_list,
            meas_id_to_add_mod_list=meas_id_to_add_mod_list,
            meas_object_to_add_mod_list_v9e0=meas_object_to_add_mod_list_v9e0,
        )

    def _find_structure_name(self, object_to_find):
        for attr_name, attr_value in self.__dict__.items():
            if object_to_find == attr_value:
                return attr_name
        return "Unknown"

    def update(
        self,
        meas_object_to_remove_list,
        report_config_to_remove_list,
        meas_id_to_remove_list,
        meas_object_to_add_mod_list,
        report_config_to_add_mod_list,
        meas_id_to_add_mod_list,
        meas_object_to_add_mod_list_v9e0,
    ):
        """
        Adds or removes measurement from measurement objects.
        """
        self._update_meas_objects(
            meas_object_to_remove_list, meas_object_to_add_mod_list, meas_object_to_add_mod_list_v9e0
        )
        self._update_report_configs(report_config_to_remove_list, report_config_to_add_mod_list)
        self._update_meas_ids(meas_id_to_remove_list, meas_id_to_add_mod_list)
        self._join_configs()
        return self

    def _join_configs(self):
        self.activeConfigs = copy.deepcopy(self.measIds)
        for value in self.activeConfigs.values():
            value["measObjectId"] = self.measObjects.get(value["measObjectId"])
            value["reportConfigId"] = self.reportConfigs.get(value["reportConfigId"])

    def __str__(self):  # noqa: C901
        tmp_meas_dump = {}
        for mId in list(self.measIds.keys()):
            meas_id_dump = []
            for report_config_id in list(self.reportConfigs.keys()):
                if str(report_config_id) == str(self.measIds[mId]["reportConfigId"]):
                    self._log_or_filter_matching_reportconfig(meas_id_dump, report_config_id, self.reportConfigs)
            for meas_object_id in list(self.measObjects.keys()):
                if str(meas_object_id) == str(self.measIds[mId]["measObjectId"]):
                    self._log_or_filter_matching_measobject(meas_id_dump, meas_object_id, self.measObjects)
            if len(meas_id_dump) == 2:
                tmp_meas_dump[mId] = copy.deepcopy(meas_id_dump)
            else:
                print("MeasId: {} omitted in dump due to logger filtering".format(mId))
        return "Current measurement dump:\n{}".format(pprint.pformat(tmp_meas_dump))

    def _log_or_filter_matching_measobject(self, meas_id_dump, meas_object_id, object_type_to_check):
        if LOGGER_DETAILS is not None and LOGGER_DETAILS["measObject"] is not None:
            measObject = self._filter_measobject_with_logger(meas_object_id, object_type_to_check)
        else:
            measObject = object_type_to_check[meas_object_id]
        if len(measObject):
            meas_id_dump.append({meas_object_id: measObject})

    def _log_or_filter_matching_reportconfig(self, meas_id_dump, report_config_id, object_type_to_check):
        if LOGGER_DETAILS is not None and LOGGER_DETAILS["reportConfig"] is not None:
            reportConfig = self._filter_reportconfig_with_logger(report_config_id, object_type_to_check)
        else:
            reportConfig = object_type_to_check[report_config_id]
        if len(reportConfig):
            meas_id_dump.append({report_config_id: reportConfig})

    def _filter_measobject_with_logger(self, meas_object_id, object_type_to_check):
        meas_object_filtered_keys = LOGGER_DETAILS["measObject"]
        measObject = []
        for measobject_filter in meas_object_filtered_keys:
            try:
                measObject.append(
                    {measobject_filter: object_type_to_check[meas_object_id].get_value_by_unique_key(measobject_filter)}
                )
            except Exception:
                measObject = []
                break
        return measObject

    def _filter_reportconfig_with_logger(self, report_config_id, object_type_to_check):
        report_config_filtered_keys = LOGGER_DETAILS["reportConfig"]
        reportConfig = []
        for report_filter in report_config_filtered_keys:
            try:
                reportConfig.append(
                    {report_filter: object_type_to_check[report_config_id].get_value_by_unique_key(report_filter)}
                )
            except Exception:
                reportConfig = []
                break
        return reportConfig

    def _get_object_location_by_content(self, object_to_check):
        objects_mapping = {"measObject": self.measObjects, "reportConfig": self.reportConfigs}
        for object_mapping_type in objects_mapping:
            if object_mapping_type in object_to_check:
                return objects_mapping[object_mapping_type]
        print(
            "Cannot map object: {} to any of mappings : {}".format(
                pprint.pformat(object_to_check), pprint.pformat(objects_mapping)
            )
        )

    def _update_meas_objects(
        self, meas_object_to_remove_list, meas_object_to_add_mod_list, meas_object_to_add_mod_list_v9e0
    ):
        self._update_object_by_remove(objs_to_update=self.measObjects, to_remove_objects=meas_object_to_remove_list)

        self._update_carrier_freq(meas_object_to_add_mod_list, meas_object_to_add_mod_list_v9e0)

        if meas_object_to_add_mod_list:
            for measObject in meas_object_to_add_mod_list:
                object_to_assign = self._get_object_location_by_content(measObject)
                try:
                    object_to_assign[measObject["measObjectId"]]
                except KeyError:
                    object_to_assign[measObject["measObjectId"]] = meas_object_factory(measObject)
                    logging.getLogger("ta_measurements").debug(
                        "Created new item in {} with content: {}".format(
                            self._find_structure_name(object_to_assign), measObject
                        )
                    )
                else:
                    logging.getLogger("ta_measurements").debug(
                        "Overwritten existing item:\n{} in {} with content:\n{}".format(
                            object_to_assign[measObject["measObjectId"]],
                            self._find_structure_name(object_to_assign),
                            measObject,
                        )
                    )
                    object_to_assign[measObject["measObjectId"]] = meas_object_factory(measObject)

    def _update_report_configs(self, report_config_to_remove_list, report_config_to_add_mod_list):
        self._update_object_by_remove(objs_to_update=self.reportConfigs, to_remove_objects=report_config_to_remove_list)

        if report_config_to_add_mod_list:
            for reportConfig in report_config_to_add_mod_list:
                object_to_assign = self._get_object_location_by_content(reportConfig)
                try:
                    object_to_assign[reportConfig["reportConfigId"]]
                except KeyError:
                    object_to_assign[reportConfig["reportConfigId"]] = report_config_object_factory(reportConfig)
                    logging.getLogger("ta_measurements").debug(
                        "Created new item in {} with content: {}".format(
                            self._find_structure_name(object_to_assign), reportConfig
                        )
                    )
                else:
                    logging.getLogger("ta_measurements").debug(
                        "Overwritten existing item:\n{} in {} with content:\n{}".format(
                            object_to_assign[reportConfig["reportConfigId"]],
                            self._find_structure_name(object_to_assign),
                            reportConfig,
                        )
                    )
                    object_to_assign[reportConfig["reportConfigId"]] = report_config_object_factory(reportConfig)

    def _update_meas_ids(self, meas_id_to_remove_list, meas_id_to_add_mod_list):
        self._update_object_by_remove(objs_to_update=self.measIds, to_remove_objects=meas_id_to_remove_list)

        if meas_id_to_add_mod_list:
            for measId in meas_id_to_add_mod_list:
                try:
                    self.measIds[measId["measId"]]
                except KeyError:
                    self.measIds[measId["measId"]] = MeasId(measId)
                    logging.getLogger("ta_measurements").debug(
                        "Created new item in {} with content: {}".format(
                            self._find_structure_name(self.measIds), measId
                        )
                    )
                else:
                    logging.getLogger("ta_measurements").debug(
                        "Overwritten existing item:\n{} in {} with content:\n{}".format(
                            self.measIds[measId["measId"]], self._find_structure_name(self.measIds), measId
                        )
                    )
                    self.measIds[measId["measId"]] = MeasId(measId)

    def _update_object_by_remove(self, objs_to_update, to_remove_objects):
        if not isinstance(objs_to_update, list):
            to_update = [objs_to_update]
        else:
            to_update = objs_to_update
        if to_remove_objects:
            for id_to_remove in to_remove_objects:
                for t_update in to_update:
                    try:
                        del t_update[id_to_remove]
                        object_name_for_logging = self._find_structure_name(to_update)
                        logging.getLogger("ta_measurements").debug(
                            "Removed: {} from structure : {}".format(id_to_remove, object_name_for_logging)
                        )
                    except KeyError:
                        pass

    def _update_carrier_freq(self, meas_object_to_add_mod_list, meas_object_to_add_mod_list_v9e0):
        """
        It is not working yet for measObjectNR
        """
        if meas_object_to_add_mod_list_v9e0:
            assert len(meas_object_to_add_mod_list) == len(
                meas_object_to_add_mod_list_v9e0
            ), "len of measObjectToAddModList ({}) not equal to measObjectToAddModList-v9e0 ({})".format(
                meas_object_to_add_mod_list, meas_object_to_add_mod_list_v9e0
            )
            for meas_object, meas_object_v9e0 in zip(meas_object_to_add_mod_list, meas_object_to_add_mod_list_v9e0):
                if meas_object_v9e0:
                    meas_object["measObject"]["measObjectEUTRA"]["carrierFreq"] = meas_object_v9e0[
                        "measObjectEUTRA-v9e0"
                    ]["carrierFreq-v9e0"]
